# Architecture:
# Blackmacro leds use an effect layer system. Each layer transforms the existing LED data procedurally. The final result is then pushed to the LED controller.
# Every frame, the LED values would be generated by the first layer, then transformed by the second, then the third, and so on.
# e.g.: Rainbow background generator -> key state visualization -> key press visualization -> user brightness control -> powersave blackout => output
import asyncio
import colorsys

import neopixel
import machine
import hardware_defs
from modules.key import Key, DEF_KEYS
from module import SysModule


class LEDLayer:
    def __init__(self):
        self.layout: dict[str, Key] = DEF_KEYS

    def key_lookup(self, led: int) -> Key:
        return next(key for key in self.layout.values() if key.led == led)

    def location_lookup(self, led: int) -> tuple[float, float]:
        """
        returns estimated physical position of the LED[index]: (y,x), origin at bottom left.
        """
        return self.key_lookup(led).position


    def process(self, data: list[tuple[int, int, int]], delta: float) -> list[tuple[int, int, int]]:
        """
        :param data: data from last layer (all black for first layer)
        :param delta: frametime in seconds
        :return: updated data
        """
        pass

class ColorGenerator(LEDLayer):
    def __init__(self, color: tuple[int, int, int]):
        super().__init__()
        self.color: tuple[int, int, int] = color

    def process(self, data: list[tuple[int, int, int]], delta: float) -> list[tuple[int, int, int]]:
        return [self.color for led in data]


class RainbowGenerator(LEDLayer):
    def __init__(self, speed: float = 5, scale: float = 1):
        super().__init__()
        self.speed: float = speed
        self.scale: float = scale
        self.t: float = 0

    # noinspection PyMethodMayBeStatic
    def t_to_rgb(self, t: float) -> tuple[int, int, int]:
        val = colorsys.hsv_to_rgb(t, 1.0, 1.0)
        return int(val[0] * 255.99), int(val[1] * 255.99), int(val[2] * 255.99)


    def process(self, data: list[tuple[int, int, int]], delta: float) -> list[tuple[int, int, int]]:
        self.t += delta * self.speed

        for idx, rgb in enumerate(data):
            loc = self.location_lookup(idx)
            rgb = self.t_to_rgb((float(loc[0] + loc[1] + self.t) * self.scale/10) % 1.0)

            data[idx] = rgb

        return data

class KeyImmediateVisualizationFX(LEDLayer):
    def __init__(self, press_color: tuple[int, int, int]):
        super().__init__()
        self.press_color: tuple[int, int, int] = press_color

    def process(self, data: list[tuple[int, int, int]], delta: float) -> list[tuple[int, int, int]]:
        for idx, rgb in enumerate(data):
            if self.key_lookup(idx).is_pressed():
                data[idx] = self.press_color
        return data


class BrightnessControlFX(LEDLayer):
    def __init__(self, brightness: float, gamma: float = 4, clamp: bool = True):
        """
        :param brightness: If clamp == True, this is the maximum brightness (255 * brightness) max component of an led can be. Values will be scaled proportionally.
        Otherwise, the leds\' values will simply be multiplied by this factor.
        :param gamma: Default 4. Defines curve for perceived brightness adjustment.
        :param clamp:
        """
        super().__init__()
        self.brightness = brightness
        self.gamma = gamma
        self.clamp = clamp

    def change_brightness_gamma(self, value: float):
        self.brightness = (value**self.gamma) * (1 ** -self.gamma)

    def process(self, data: list[tuple[int, int, int]], delta: float) -> list[tuple[int, int, int]]:
        # print(self.brightness)
        for idx, led in enumerate(data):
            if self.clamp:
                factor = (self.brightness * 255) / max(led[0], led[1], led[2])
                data[idx] = (int(led[0] * factor), int(led[1] * factor),
                             int(led[2] * factor))
            else:
                data[idx] = (int(led[0] * self.brightness), int(led[1] * self.brightness), int(led[2] * self.brightness))

        return data
# =====

class LEDController(SysModule):
    def __init__(self, delta: float = 0.02, layers=None):
        super().__init__(delta)
        if layers is None:
            layers = []
        self.layers: list[LEDLayer] = layers
        self.pin = machine.Pin(hardware_defs.P_LED, machine.Pin.OUT)
        self.leds = neopixel.NeoPixel(self.pin, hardware_defs.COUNT_LED)

    async def update(self):
        data: list[tuple[int, int, int]] = [(0,0,0) for i in range(hardware_defs.COUNT_LED)]
        for layer in self.layers:
            data = layer.process(data, self.delta)

        # clamp to max brightness :(
        data = [(min(255, pix[0]), min(255, pix[1]), min(255, pix[2])) for pix in data]

        # push to leds
        self.leds.fill((0,0,0))
        for idx, val in enumerate(data):
            self.leds[idx] = val

        self.leds.write()